ext('c12_eng_ch17',[
C("⚔️","प्रथम विश्व युद्ध की पृष्ठभूमि",["1914 से 1918 तक चला युद्ध","लाखों सैनिक मारे गए","भारत से भी लाखों सैनिक गए","कविता युद्ध के आरंभ में लिखी"],"इस कविता की पृष्ठभूमि प्रथम विश्व युद्ध है, जो उन्नीस सौ चौदह में शुरू हुआ और उन्नीस सौ अठारह तक चला। यह इतिहास के सबसे बड़े युद्धों में से एक था, जिसमें लाखों सैनिक मारे गए। भारत से भी लगभग पंद्रह लाख सैनिक ब्रिटिश सेना के साथ दूर-दूर के मोर्चों पर लड़े, जिनमें बिहार के भी बहुत से जवान थे। रूपर्ट ब्रुक ने यह कविता युद्ध के शुरुआती दौर में लिखी, जब कई युवाओं में जोश और देशभक्ति की भावना थी। बाद में युद्ध की भयावहता देखकर कई कवियों ने अपने स्वर बदल लिए।"),
C("✍️","रूपर्ट ब्रुक का जीवन",["जन्म 1887 इंग्लैंड","युवा और आदर्शवादी कवि","1915 में नौसेना में सेवा के दौरान निधन","लड़ाई में नहीं, बीमारी से मृत्यु"],"रूपर्ट ब्रुक इंग्लैंड के युवा और आदर्शवादी कवि थे। वे अपनी सुंदरता और प्रतिभा के लिए प्रसिद्ध थे। प्रथम विश्व युद्ध के दौरान वे नौसेना में भर्ती हुए और उन्नीस सौ पंद्रह में बहुत कम उम्र में एक संक्रमण से उनका निधन हो गया। यानी वे सीधे लड़ाई में नहीं मरे, पर उनके पाँच युद्ध सॉनेट, जिनमें द सोल्जर शामिल है, उनकी मृत्यु के बाद बहुत प्रसिद्ध हुए। उन्हें उस दौर के देशभक्ति के प्रतीक कवि की तरह देखा गया। परीक्षा में कवि का नाम, देश और रचना का वर्ष याद रखिए।"),
C("🧩","सॉनेट का स्वरूप",["चौदह पंक्तियों की कविता","पहले आठ और बाद के छह","आठ को ऑक्टेव और छह को सेस्टेट कहते हैं","पेट्रार्कन शैली"],"द सोल्जर एक सॉनेट है। सॉनेट चौदह पंक्तियों की कविता होती है। इसे दो भागों में बाँटा जाता है। पहले आठ पंक्तियों को ऑक्टेव कहते हैं और बाद की छह को सेस्टेट। यह कविता पेट्रार्कन शैली में है, जिसमें पहला भाग एक विचार रखता है और दूसरा भाग उसका उत्तर या निष्कर्ष। यहाँ पहले भाग में सैनिक अपने देश इंग्लैंड की धरती से बने अपने शरीर और उसके प्रति प्रेम की बात करता है, और दूसरे भाग में मृत्यु के बाद भी देश से जुड़े रहने की भावना बताता है। सॉनेट का रूप परीक्षा में अवश्य पूछा जाता है।"),
C("🌍","विदेशी धरती का एक कोना",["मैं मरूँ तो यही सोचना","विदेश की धरती का कोना इंग्लैंड होगा","शरीर इंग्लैंड की मिट्टी का बना","पहचान देश से जुड़ी"],"कविता का सबसे प्रसिद्ध विचार यह है कि अगर सैनिक किसी विदेशी धरती पर मारा जाए, तो उस धरती का एक छोटा सा कोना हमेशा के लिए अपने देश का हो जाएगा। कारण यह है कि उसका शरीर अपने देश की मिट्टी, फूलों, हवा और नदियों से बना है। यानी वह जहाँ भी जाए, अपने देश की पहचान साथ ले जाता है। यह विचार भावुक भी है और काव्यात्मक भी। यही बात हर प्रवासी के लिए भी सच है, चाहे वह बिहार का कोई श्रमिक या जवान हो, जो घर से दूर रहकर भी अपने गाँव को अपने भीतर ज़िंदा रखता है।"),
C("🌸","इंग्लैंड की प्रकृति के बिंब",["फूल, नदियाँ, धूप","हवा और सुगंध","अपनी मिट्टी का पोषण","देश के प्रति कृतज्ञता"],"कविता के दूसरे भाग में इंग्लैंड की प्रकृति के सुंदर बिंब हैं। कवि फूलों, नदियों, सूरज की धूप और हवा का ज़िक्र करते हैं। वे बताते हैं कि इसी भूमि ने उसे जन्म दिया, खिलाया-पिलाया और बड़ा किया। इसलिए वह इस भूमि का ऋणी है। यहाँ कवि का देशप्रेम केवल झंडे या नारों का नहीं, बल्कि अपनी धरती के प्रकृति-सौंदर्य, उसके मौसम और उसकी ख़ुशबू के प्रति गहरे अपनत्व का है। हमारे यहाँ भी कहा गया है कि जननी और जन्मभूमि स्वर्ग से भी बढ़कर हैं।"),
C("🛡️","देशभक्ति और बलिदान",["देश के लिए प्राण देना सम्मान","मातृभूमि का ऋण","आदर्शवाद","अटूट जुड़ाव"],"कविता में देशभक्ति का स्वर बहुत स्पष्ट है। कवि के लिए देश के लिए बलिदान देना गर्व की बात है और मृत्यु भी देश से जुड़ाव को समाप्त नहीं कर सकती। यह आदर्शवादी दृष्टि है। भारत में भी शहीदों को इसी श्रद्धा से याद किया जाता है, चाहे वह स्वतंत्रता संग्राम के वीर हों या सीमा पर तैनात जवान। पर आगे चलकर वेल्फ्रेड ओवेन जैसे कवियों ने युद्ध की भयावह सच्चाई दिखाई। इसलिए परीक्षा में ब्रुक की कविता को आदर्शवादी या रोमांटिक देशभक्ति की कविता कहना ठीक रहेगा।"),
C("🎨","भाषा और शैली",["सरल, लयात्मक भाषा","आपसी तुकबंदी","रोमांटिक और आदर्शवादी स्वर","शांत गरिमा"],"कविता की भाषा सरल और लयात्मक है। सॉनेट की तुक योजना कविता को संगीत जैसी गति देती है। स्वर आदर्शवादी और रोमांटिक है, यानी इसमें भावना और कल्पना को प्रधानता दी गई है। कवि के शब्दों में गरिमा और शांति है, कोई कठोरता या क्रोध नहीं। वे मृत्यु की बात करते हैं, पर बिना डर या कड़वाहट के। इसी शांत आत्मविश्वास के कारण यह कविता बहुत लोकप्रिय हुई। परीक्षा में शैली लिखें, तो सरल भाषा, सॉनेट रूप, रोमांटिक भावना और प्रकृति के बिंब, ये चार बिंदु दीजिए।"),
C("📝","शब्दार्थ दोहराइए",["सोल्जर यानी सैनिक","फ़ॉरेन यानी विदेशी","डस्ट यानी मिट्टी","मदरलैंड यानी मातृभूमि"],"आइए शब्द दोहराएँ। सोल्जर यानी सैनिक, फ़ॉरेन यानी विदेशी, डस्ट यानी मिट्टी, सॉयल यानी धरती और मदरलैंड यानी मातृभूमि। साथ में सैक्रिफ़ाइस यानी बलिदान, पैट्रियटिज़्म यानी देशभक्ति और होमलैंड यानी स्वदेश भी याद कर लीजिए। अब हर शब्द से अपना वाक्य बनाइए। जैसे ए सोल्जर लव्स हिज़ मदरलैंड, यानी सैनिक अपनी मातृभूमि से प्यार करता है। और ही सैक्रिफ़ाइस्ड हिज़ लाइफ़ फ़ॉर हिज़ कंट्री, यानी उसने देश के लिए प्राण दे दिए।"),
C("🧩","व्याकरण: कंडिशनल वाक्य",["इफ़ आई डाई, थिंक ओनली दिस","पहला और दूसरा प्रकार","शर्त और परिणाम","इफ़ के बाद कॉमा"],"कविता की शुरुआत इफ़ वाले वाक्य से होती है, यानी अगर मैं मरूँ। इसे कंडिशनल वाक्य कहते हैं, जिसमें एक शर्त और उसका परिणाम होता है। पहले प्रकार में इफ़ के साथ वर्तमान काल और परिणाम में विल लगता है, जैसे इफ़ यू स्टडी हार्ड, यू विल पास। दूसरे प्रकार में इफ़ के साथ भूतकाल और परिणाम में वुड आता है, जैसे इफ़ आई वर बर्ड, आई वुड फ़्लाई। अपने जीवन की शर्तों पर चार कंडिशनल वाक्य बनाइए।"),
C("🏞️","बिहार के जवान और देश",["भारतीय सेना में बिहार रेजिमेंट","सैनिक परिवारों का त्याग","गाँव की मिट्टी की याद","शहीदों का सम्मान"],"बिहार का भी सेना से गहरा रिश्ता है। बिहार रेजिमेंट भारतीय सेना की एक प्रसिद्ध रेजिमेंट है और यहाँ के गाँवों से हर वर्ष बहुत से युवा सेना में जाते हैं। उनके परिवार भी त्याग करते हैं, क्योंकि बेटा घर से दूर, कठिन परिस्थितियों में देश की सेवा करता है। जैसे इस कविता का सैनिक अपने देश की मिट्टी को याद करता है, वैसे ही हमारे जवान अपने गाँव की मिट्टी, खेत और माँ की रोटी को याद करते हैं। कविता पढ़ते समय इन जवानों के प्रति कृतज्ञता का भाव ज़रूर रखिए।"),
C("📌","कविता का सार",["सैनिक विदेश में मरे तो वहाँ इंग्लैंड का कोना","शरीर इंग्लैंड की मिट्टी से बना","प्रकृति और स्मृतियाँ देश से जुड़ाव","संदेश: मातृभूमि से अटूट प्रेम"],"अब कविता का सार दोहरा लें। रूपर्ट ब्रुक की द सोल्जर में एक सैनिक कहता है कि अगर वह विदेश में मरे, तो उस धरती का एक कोना हमेशा इंग्लैंड हो जाएगा। उसका शरीर इंग्लैंड की मिट्टी, फूल और हवा से बना है और मृत्यु के बाद भी वह अपने देश से जुड़ा रहता है। कविता एक सॉनेट है, जिसका स्वर आदर्शवादी और देशभक्ति से भरा है। संदेश है कि मातृभूमि से प्रेम अटूट है और उसके लिए बलिदान सम्मान की बात है। इसे अपने शब्दों में लिखकर देखिए।"),
C("❓","संभावित परीक्षा प्रश्न",["कवि और कविता का रूप","सैनिक क्या कहता है","कविता का मूल भाव","सॉनेट की बनावट"],"परीक्षा के प्रश्न देखिए। पहला, कवि कौन हैं और कविता का रूप क्या है? उत्तर, रूपर्ट ब्रुक, सॉनेट। दूसरा, सैनिक क्या कहता है? उत्तर, कि विदेश में मरने पर भी वह धरती का कोना इंग्लैंड का हो जाएगा। तीसरा, मूल भाव? उत्तर, मातृभूमि से अटूट प्रेम और बलिदान का गौरव। चौथा, सॉनेट की बनावट? उत्तर, चौदह पंक्तियाँ, पहले आठ और बाद के छह। पूरे वाक्य में उत्तर लिखिए।"),
Q("आपके अनुसार देशभक्ति केवल सीमा पर लड़ने वालों की होती है या हर नागरिक की?","हर नागरिक की, क्योंकि ईमानदारी से अपना काम करना और देश की संपत्ति बचाना भी देशभक्ति है।","एक सोचने वाला प्रश्न। आपके अनुसार देशभक्ति केवल सीमा पर लड़ने वालों की होती है या हर नागरिक की? सोचिए। ... हर नागरिक की, क्योंकि ईमानदारी से अपना काम करना, नियमों का पालन करना और देश की संपत्ति बचाना भी देशभक्ति है। विद्यार्थी का मन लगाकर पढ़ना भी देश की सेवा है।"),
],7)
